 insert into res values($n$PF1 add-only: create product with branches [B1] ok, product row, availability row (B1, available), created and availability audit$n$, r='ok' and pg_temp.q('select count(*)::text from products where name=''PF-A1''')='1' and pg_temp.q('select count(*)::text from product_branches pb join products p on p.id=pb.product_id where p.name=''PF-A1'' and pb.branch_id=''fb010000-0000-4000-8000-000000000001'' and pb.available')='1' and pg_temp.q('select count(*)::text from audit_events where action=''product.created''')>='1' and pg_temp.q('select count(*)::text from audit_events where action=''product.availability_changed''')>='1', r);
 insert into res values($n$PF2 add-only, user in B1 only: create with branches [B1,B2] refused 42501 branch not permitted, whole create rolled back (no product, no availability row)$n$, r like '42501|FORBIDDEN: branch not permitted%' and pg_temp.q('select count(*)::text from products where name=''PF-A2''')='0' and pg_temp.q('select count(*)::text from product_branches pb join products p on p.id=pb.product_id where p.name=''PF-A2''')='0', r);
 insert into res values($n$PF3 add-only: create with a foreign-org branch refused P0001 VALIDATION product_branch, no product and no availability row$n$, r like 'P0001|VALIDATION: product_branch%' and pg_temp.q('select count(*)::text from products where name=''PF-A3''')='0' and pg_temp.q('select count(*)::text from product_branches pb join products p on p.id=pb.product_id where p.name=''PF-A3''')='0', r);
 insert into res values($n$PF4 add-only: non-array branches refused P0001 VALIDATION product_branch, nothing saved$n$, r like 'P0001|VALIDATION: product_branch%' and pg_temp.q('select count(*)::text from products where name=''PF-A4''')='0', r);
 insert into res values($n$PF5 add-only: create without a branches key unchanged: product row, zero availability rows$n$, r='ok' and pg_temp.q('select count(*)::text from products where name=''PF-A5''')='1' and pg_temp.q('select count(*)::text from product_branches pb join products p on p.id=pb.product_id where p.name=''PF-A5''')='0', r);
 insert into res values($n$PF6 add-only: category create ok (row), category update refused 42501 page edit and name unchanged$n$, r='ok' and pg_temp.q('select count(*)::text from product_categories where name=''PF-cat-A''')='1' and ar like '42501|FORBIDDEN: page /admin/products action edit%' and pg_temp.q('select count(*)::text from product_categories where id=''fbc00000-0000-4000-8000-000000000001'' and name=''PF cat''')='1', r||' / '||ar);
 insert into res values($n$PF7 add-only: product update (price) and set-availability refused 42501 page edit, price and availability unchanged$n$, r like '42501|FORBIDDEN: page /admin/products action edit%' and ar like '42501|FORBIDDEN: page /admin/products action edit%' and pg_temp.q('select count(*)::text from products where id=''fbd00000-0000-4000-8000-000000000001'' and price_halalas=1000 and version=1')='1' and pg_temp.q('select count(*)::text from product_branches where product_id=''fbd00000-0000-4000-8000-000000000001'' and branch_id=''fb010000-0000-4000-8000-000000000001'' and available')='1', r||' / '||ar);
