 insert into res values($n$PF9 edit-only: price update ok (price 1500, version 2) and availability toggle ok (B1 off)$n$, r='ok' and ar='ok' and pg_temp.q('select count(*)::text from products where id=''fbd00000-0000-4000-8000-000000000001'' and price_halalas=1500 and version=2')='1' and pg_temp.q('select count(*)::text from product_branches where product_id=''fbd00000-0000-4000-8000-000000000001'' and branch_id=''fb010000-0000-4000-8000-000000000001'' and not available')='1', r||' / '||ar);
