 insert into res values($n$PF11 branch-limited edit user: availability change in B2 refused 42501 branch not permitted, no row change$n$, r like '42501|FORBIDDEN: branch not permitted%' and pg_temp.q('select count(*)::text from product_branches where product_id=''fbd00000-0000-4000-8000-000000000002'' and branch_id=''fb010000-0000-4000-8000-000000000002'' and available')='1', r);
